import javax.tools.*;import java.nio.file.*;import java.net.*;import java.util.*;

/** Exercises the actual square component's measurement and ImageView scaling policy. */
public final class SquarePreviewRegression {
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]),dir=root.resolve("build/square-preview-tests"),classes=dir.resolve("classes");Files.createDirectories(classes);List<String> files=new ArrayList<>();
  ExposurePipelineRegression.write(dir,files,"android/content/Context.java","package android.content;public class Context{}");
  ExposurePipelineRegression.write(dir,files,"android/view/View.java","package android.view;public class View{public static final int IMPORTANT_FOR_ACCESSIBILITY_NO=2;public static class MeasureSpec{public static final int EXACTLY=0x40000000,AT_MOST=0x80000000,UNSPECIFIED=0;public static int getSize(int n){return n&0x3fffffff;}public static int makeMeasureSpec(int size,int mode){return size|mode;}}}");
  ExposurePipelineRegression.write(dir,files,"android/widget/ImageView.java","package android.widget;public class ImageView extends android.view.View{public enum ScaleType{FIT_CENTER,CENTER_CROP}public ScaleType scale;public Object params;public ImageView(android.content.Context c){}public void setScaleType(ScaleType s){scale=s;}public void setImportantForAccessibility(int n){}}");
  ExposurePipelineRegression.write(dir,files,"android/widget/FrameLayout.java","package android.widget;public class FrameLayout extends android.view.View{public int measuredWidth,measuredHeight;public ImageView child;public FrameLayout(android.content.Context c){}public static class LayoutParams{public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public void addView(ImageView view,LayoutParams p){child=view;view.params=p;}protected void onMeasure(int w,int h){measuredWidth=MeasureSpec.getSize(w);measuredHeight=MeasureSpec.getSize(h);}}");
  ExposurePipelineRegression.write(dir,files,"com/silverroom/camera/SquareProbe.java","package com.silverroom.camera;import java.util.*;import android.view.View.MeasureSpec;import android.widget.*;public class SquareProbe{public static List<String> run(){List<String> result=new ArrayList<>();SquarePreview p=new SquarePreview(new android.content.Context());for(int width:new int[]{0,80,144,194,288,408,864})for(int mode:new int[]{MeasureSpec.EXACTLY,MeasureSpec.AT_MOST})for(int height:new int[]{1,80,600}){p.onMeasure(MeasureSpec.makeMeasureSpec(width,mode),MeasureSpec.makeMeasureSpec(height,MeasureSpec.AT_MOST));if(p.measuredWidth!=width||p.measuredHeight!=width)throw new AssertionError(\"preview must stay square independently of captions/row height\");}result.add(\"Production preview stays square for all tested grid widths and changing parent/caption heights\");if(p.image!=p.child||p.image.scale!=ImageView.ScaleType.CENTER_CROP)throw new AssertionError(\"must crop rather than letterbox\");FrameLayout.LayoutParams params=(FrameLayout.LayoutParams)p.image.params;if(params.width!=-1||params.height!=-1)throw new AssertionError(\"image must occupy the entire square\");result.add(\"Production ImageView uses CENTER_CROP and fills both dimensions of the square, without letterboxing or stretching\");return result;}}");
  files.add(root.resolve("src/com/silverroom/camera/SquarePreview.java").toString());List<String> options=new ArrayList<>(Arrays.asList("--release","8","-encoding","UTF-8","-d",classes.toString()));options.addAll(files);if(ToolProvider.getSystemJavaCompiler().run(null,null,null,options.toArray(new String[0]))!=0)throw new AssertionError("Square preview fixture compile");
  try(URLClassLoader loader=new URLClassLoader(new URL[]{classes.toUri().toURL()},null)){try{for(Object line:(List<?>)loader.loadClass("com.silverroom.camera.SquareProbe").getMethod("run").invoke(null))System.out.println("PASS "+line);}catch(java.lang.reflect.InvocationTargetException e){throw new AssertionError("Square preview",e.getCause());}}
 }
}
